        ? { type: "apiKey" as const, id: authentication.apiKeyId }
        : null;

    if (!actor) {
      return problemForbidden(requestId, undefined, instance);
    }

    const canManage = await assertCan(actor, "apiKey.manage", {
      type: "apiKey",
      id: apiKeyId,
    });

