 * Session cookie or x-api-key; the caller must hold `apiKey.manage` on the key.
 * Returns the new plaintext key (shown once, like create).
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZId } from "@formbricks/types/common";
import { z } from "zod";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import { mapV3ThrownError } from "@/app/api/v3/lib/errors";
import { logger } from "@formbricks/logger";
import { successResponse } from "@/app/api/v3/lib/response";

const ZRotateApiKeyParams = z.strictObject({
  apiKeyId: z.string().cuid2(),
});

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "updated",
  targetType: "apiKey",
  schemas: { params: ZRotateApiKeyParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) => {
    const { apiKeyId } = parsedInput.params;

    // Build the actor from the authentication result
    const actor =
      authentication && "user" in authentication && authentication.user?.id
        ? { type: "user" as const, id: authentication.user.id }
        : authentication && "apiKeyId" in authentication
          ? { type: "apiKey" as const, id: authentication.apiKeyId }
          : null;

    if (!actor) {
      throw new Error("Unauthenticated");
    }

    // Verify the caller can manage this API key (throws on failure)
    await assertCan(actor, "apiKey.manage", {
      type: "apiKey",
      id: apiKeyId,
    });

    const organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);
    auditLog!.organizationId = organizationId;
    auditLog!.apiKeyId = apiKeyId;

    const result = await rotateApiKey(apiKeyId);
    auditLog!.newObject = { apiKeyId };
    return successResponse(
      {
        apiKeyId: result.id,
        actualKey: result.actualKey,
      },
      { requestId }
    );
  },
});

